-- Run in Supabase SQL Editor. Review transport compliance before enabling paid passenger operations.
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,first_name text not null default '',surname text not null default '',phone text default '',home_area text default '',created_at timestamptz default now());
create table if not exists public.driver_profiles(user_id uuid primary key references public.profiles(id) on delete cascade,display_name text not null default '',contact_phone text default '',bio text default '',verified boolean not null default false,created_at timestamptz default now());
create table if not exists public.vehicles(id uuid primary key default gen_random_uuid(),driver_id uuid not null references public.profiles(id) on delete cascade,make text not null,model text not null,registration text not null,seat_capacity int not null check(seat_capacity between 1 and 20),approved boolean not null default false,created_at timestamptz default now());
create table if not exists public.trips(id uuid primary key default gen_random_uuid(),driver_id uuid not null references public.profiles(id),vehicle_id uuid not null references public.vehicles(id),origin text not null,destination text not null,departure_at timestamptz not null,service_type text not null check(service_type in ('morning','afternoon','evening','night')),price_per_seat numeric(10,2) not null check(price_per_seat>=0),seats_total int not null check(seats_total between 1 and 20),seats_available int not null check(seats_available>=0 and seats_available<=seats_total),pickup_point text not null,notes text default '',status text not null default 'published' check(status in ('published','cancelled','completed')),created_at timestamptz default now());
create table if not exists public.bookings(id uuid primary key default gen_random_uuid(),trip_id uuid not null references public.trips(id),passenger_id uuid not null references public.profiles(id),seats int not null check(seats between 1 and 20),pickup_note text not null,gate_requested boolean not null default false,total_base_fare numeric(10,2) not null check(total_base_fare>=0),status text not null default 'requested' check(status in ('requested','confirmed','declined','cancelled','completed')),created_at timestamptz default now());
create table if not exists public.ride_requests(id uuid primary key default gen_random_uuid(),passenger_id uuid not null references public.profiles(id),origin text not null,destination text not null,travel_date date not null,service_type text not null check(service_type in ('morning','afternoon','evening','night')),seats int not null check(seats between 1 and 20),status text not null default 'searching' check(status in ('searching','already_taken','cancelled')),created_at timestamptz default now());
create table if not exists public.parcel_requests(id uuid primary key default gen_random_uuid(),sender_id uuid not null references public.profiles(id),origin text not null,destination text not null,description text not null,recipient_phone text not null,weight_kg numeric(10,2) not null check(weight_kg>0),offered_fee numeric(10,2) not null check(offered_fee>0),status text not null default 'pending' check(status in ('pending','accepted','collected','in_transit','delivered','cancelled')),created_at timestamptz default now());
create table if not exists public.emergency_contacts(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,name text not null,phone text not null,created_at timestamptz default now());
create table if not exists public.incident_reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references public.profiles(id),category text not null,description text not null,status text not null default 'open',created_at timestamptz default now());
create table if not exists public.reviews(id uuid primary key default gen_random_uuid(),booking_id uuid not null references public.bookings(id),reviewer_id uuid not null references public.profiles(id),reviewee_id uuid not null references public.profiles(id),stars int not null check(stars between 1 and 5),comment text default '',created_at timestamptz default now(),unique(booking_id,reviewer_id));
create index if not exists trips_lookup on public.trips(status,origin,destination,departure_at);
create index if not exists bookings_trip_status on public.bookings(trip_id,status);
create index if not exists bookings_passenger on public.bookings(passenger_id);
create index if not exists parcel_sender on public.parcel_requests(sender_id);
-- Signup trigger; function is internal and does not trust user metadata for authorization.
create or replace function public.create_profile() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.profiles(id,first_name,surname,phone,home_area) values(new.id,coalesce(new.raw_user_meta_data->>'first_name',''),coalesce(new.raw_user_meta_data->>'surname',''),coalesce(new.raw_user_meta_data->>'phone',''),coalesce(new.raw_user_meta_data->>'home_area',''));return new;end$$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.create_profile();
revoke all on function public.create_profile() from public,anon,authenticated;
-- RLS: no user can approve their own driver/vehicle profile.
alter table public.profiles enable row level security;
alter table public.driver_profiles enable row level security;
alter table public.vehicles enable row level security;
alter table public.trips enable row level security;
alter table public.bookings enable row level security;
alter table public.ride_requests enable row level security;
alter table public.parcel_requests enable row level security;
alter table public.emergency_contacts enable row level security;
alter table public.incident_reports enable row level security;
alter table public.reviews enable row level security;
create policy "profile own read" on public.profiles for select to authenticated using(id=(select auth.uid()));
create policy "profile own edit" on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy "driver public read" on public.driver_profiles for select to authenticated using(verified or user_id=(select auth.uid()));
create policy "driver self create" on public.driver_profiles for insert to authenticated with check(user_id=(select auth.uid()) and verified=false);
-- Never permit self-edit of verified field: update through restricted RPC.
create or replace function public.update_driver_bio(p_display_name text,p_contact_phone text,p_bio text) returns void language plpgsql security definer set search_path='' as $$begin if auth.uid() is null then raise exception 'Not authenticated';end if;insert into public.driver_profiles(user_id,display_name,contact_phone,bio) values(auth.uid(),left(p_display_name,90),left(p_contact_phone,40),left(p_bio,300)) on conflict(user_id) do update set display_name=excluded.display_name,contact_phone=excluded.contact_phone,bio=excluded.bio;end$$;
revoke all on function public.update_driver_bio(text,text,text) from public,anon;grant execute on function public.update_driver_bio(text,text,text) to authenticated;
create policy "vehicle own read" on public.vehicles for select to authenticated using(driver_id=(select auth.uid()) or approved);
create policy "vehicle own insert" on public.vehicles for insert to authenticated with check(driver_id=(select auth.uid()) and approved=false);
create policy "trip read" on public.trips for select to authenticated using((status='published' and departure_at>now()) or driver_id=(select auth.uid()));
-- For public trip browsing without sign-in, allow only published trips; no private phone fields included.
create policy "published trip public" on public.trips for select to anon using(status='published' and departure_at>now());
-- Secure trip creation validates vehicle ownership and driver approval, and price policy.
create or replace function public.publish_trip(p_vehicle_id uuid,p_origin text,p_destination text,p_departure_at timestamptz,p_service_type text,p_seats int,p_pickup text,p_notes text) returns uuid language plpgsql security definer set search_path='' as $$declare v public.vehicles%rowtype;tid uuid;fare numeric;begin if auth.uid() is null then raise exception 'Sign in required';end if;select * into v from public.vehicles where id=p_vehicle_id and driver_id=auth.uid() and approved=true;if not found or not exists(select 1 from public.driver_profiles where user_id=auth.uid() and verified=true) then raise exception 'Driver and vehicle approval required';end if;if p_origin=p_destination or p_departure_at<=now() or p_seats<1 or p_seats>v.seat_capacity then raise exception 'Invalid trip details';end if;fare:=case p_service_type when 'morning' then 500 when 'afternoon' then 500 when 'evening' then 550 when 'night' then 650 else null end;if fare is null then raise exception 'Invalid service';end if;insert into public.trips(driver_id,vehicle_id,origin,destination,departure_at,service_type,price_per_seat,seats_total,seats_available,pickup_point,notes) values(auth.uid(),p_vehicle_id,left(p_origin,100),left(p_destination,100),p_departure_at,p_service_type,fare,p_seats,p_seats,left(p_pickup,180),left(p_notes,500)) returning id into tid;return tid;end$$;
revoke all on function public.publish_trip(uuid,text,text,timestamptz,text,int,text,text) from public,anon;grant execute on function public.publish_trip(uuid,text,text,timestamptz,text,int,text,text) to authenticated;
create policy "bookings own read" on public.bookings for select to authenticated using(passenger_id=(select auth.uid()) or exists(select 1 from public.trips t where t.id=trip_id and t.driver_id=(select auth.uid())));
create policy "ride request own read" on public.ride_requests for select to authenticated using(passenger_id=(select auth.uid()));
create policy "ride request create" on public.ride_requests for insert to authenticated with check(passenger_id=(select auth.uid()) and status='searching');
create policy "ride request own update" on public.ride_requests for update to authenticated using(passenger_id=(select auth.uid())) with check(passenger_id=(select auth.uid()) and status in ('already_taken','cancelled'));
create policy "parcel own read" on public.parcel_requests for select to authenticated using(sender_id=(select auth.uid()));
create policy "parcel own insert" on public.parcel_requests for insert to authenticated with check(sender_id=(select auth.uid()) and status='pending');
create policy "contact own read" on public.emergency_contacts for select to authenticated using(user_id=(select auth.uid()));
create policy "contact own insert" on public.emergency_contacts for insert to authenticated with check(user_id=(select auth.uid()));
create policy "contact own delete" on public.emergency_contacts for delete to authenticated using(user_id=(select auth.uid()));
create policy "report own read" on public.incident_reports for select to authenticated using(reporter_id=(select auth.uid()));
create policy "report own insert" on public.incident_reports for insert to authenticated with check(reporter_id=(select auth.uid()) and status='open');
create policy "review public read" on public.reviews for select to authenticated using(true);
-- Booking requests do not reserve seats; accepting one reserves them atomically.
create or replace function public.request_booking(p_trip_id uuid,p_seats int,p_pickup_note text,p_gate_requested boolean) returns uuid language plpgsql security definer set search_path='' as $$declare t public.trips%rowtype;bid uuid;begin if auth.uid() is null then raise exception 'Sign in required';end if;select * into t from public.trips where id=p_trip_id and status='published' and departure_at>now();if not found then raise exception 'Trip unavailable';end if;if t.driver_id=auth.uid() then raise exception 'Cannot book own trip';end if;if p_seats<1 or p_seats>t.seats_available then raise exception 'Not enough seats';end if;insert into public.bookings(trip_id,passenger_id,seats,pickup_note,gate_requested,total_base_fare) values(p_trip_id,auth.uid(),p_seats,left(p_pickup_note,250),p_gate_requested,p_seats*t.price_per_seat) returning id into bid;return bid;end$$;
create or replace function public.accept_booking(p_booking_id uuid) returns void language plpgsql security definer set search_path='' as $$declare b public.bookings%rowtype;t public.trips%rowtype;begin if auth.uid() is null then raise exception 'Sign in required';end if;select * into b from public.bookings where id=p_booking_id;if not found then raise exception 'Booking not found';end if;select * into t from public.trips where id=b.trip_id for update;if t.driver_id<>auth.uid() then raise exception 'Not your trip';end if;select * into b from public.bookings where id=p_booking_id for update;if b.status<>'requested' or t.status<>'published' or t.departure_at<=now() then raise exception 'Booking unavailable';end if;if t.seats_available<b.seats then raise exception 'Not enough seats';end if;update public.trips set seats_available=seats_available-b.seats where id=t.id;update public.bookings set status='confirmed' where id=b.id;end$$;
create or replace function public.decline_booking(p_booking_id uuid) returns void language plpgsql security definer set search_path='' as $$declare b public.bookings%rowtype;begin select b0.* into b from public.bookings b0 join public.trips t on t.id=b0.trip_id where b0.id=p_booking_id and t.driver_id=auth.uid() for update of b0;if not found or b.status<>'requested' then raise exception 'Cannot decline';end if;update public.bookings set status='declined' where id=b.id;end$$;
create or replace function public.cancel_booking(p_booking_id uuid) returns void language plpgsql security definer set search_path='' as $$declare b public.bookings%rowtype;t public.trips%rowtype;begin select trip_id into b from public.bookings where id=p_booking_id;if not found then raise exception 'Booking missing';end if;select * into t from public.trips where id=b.trip_id for update;select * into b from public.bookings where id=p_booking_id for update;if b.passenger_id<>auth.uid() then raise exception 'Not your booking';end if;if b.status not in ('requested','confirmed') then raise exception 'Cannot cancel';end if;if b.status='confirmed' then update public.trips set seats_available=seats_available+b.seats where id=t.id;end if;update public.bookings set status='cancelled' where id=b.id;end$$;
create or replace function public.complete_booking(p_booking_id uuid) returns void language plpgsql security definer set search_path='' as $$begin update public.bookings b set status='completed' from public.trips t where b.id=p_booking_id and t.id=b.trip_id and t.driver_id=auth.uid() and b.status='confirmed';if not found then raise exception 'Not permitted or not confirmed';end if;end$$;
create or replace function public.review_booking(p_booking_id uuid,p_stars int,p_comment text) returns void language plpgsql security definer set search_path='' as $$declare b public.bookings%rowtype;d uuid;begin select * into b from public.bookings where id=p_booking_id and status='completed';if not found or b.passenger_id<>auth.uid() then raise exception 'Not eligible to review';end if;select driver_id into d from public.trips where id=b.trip_id;if p_stars<1 or p_stars>5 then raise exception 'Invalid rating';end if;insert into public.reviews(booking_id,reviewer_id,reviewee_id,stars,comment) values(p_booking_id,auth.uid(),d,p_stars,left(p_comment,500));end$$;
revoke all on function public.request_booking(uuid,int,text,boolean),public.accept_booking(uuid),public.decline_booking(uuid),public.cancel_booking(uuid),public.complete_booking(uuid),public.review_booking(uuid,int,text) from public,anon;
grant execute on function public.request_booking(uuid,int,text,boolean),public.accept_booking(uuid),public.decline_booking(uuid),public.cancel_booking(uuid),public.complete_booking(uuid),public.review_booking(uuid,int,text) to authenticated;
-- Restrict columns exposed for driver and vehicle writes. Avoid general UPDATE policies.
grant select,update(first_name,surname,phone,home_area) on public.profiles to authenticated;
grant select,insert on public.driver_profiles,public.vehicles,public.ride_requests,public.parcel_requests,public.emergency_contacts,public.incident_reports to authenticated;
grant update(status) on public.ride_requests to authenticated;
grant delete on public.emergency_contacts to authenticated;
grant select on public.trips to anon,authenticated;
grant select on public.bookings,public.reviews to authenticated;
-- Publish trips and booking mutations only via the RPC functions above.
